#!/usr/bin/env node

import assert from "node:assert/strict";
import { spawn, spawnSync } from "node:child_process";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const cliRequire = createRequire(path.join(repoRoot, "mcpfn/cli/package.json"));
const jiti = path.join(path.dirname(cliRequire.resolve("jiti/package.json")), "lib/jiti-cli.mjs");
const serverSource = path.join(repoRoot, "mcpfn/examples/calculator-http-server.ts");
const clientSource = path.join(repoRoot, "mcpfn/examples/calculator-client.ts");

function waitForServerUrl(child) {
  return new Promise((resolve, reject) => {
    let stdout = "";
    let stderr = "";
    const timer = setTimeout(() => {
      reject(new Error(`Calculator server did not start in time\n${stderr}`));
    }, 10_000);
    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stdout.on("data", (chunk) => {
      stdout += chunk;
      const match = /http:\/\/127\.0\.0\.1:\d+\/mcp/.exec(stdout);
      if (match) {
        clearTimeout(timer);
        resolve(match[0]);
      }
    });
    child.stderr.on("data", (chunk) => {
      stderr += chunk;
    });
    child.once("exit", (code, signal) => {
      clearTimeout(timer);
      reject(new Error(
        `Calculator server exited before startup (code=${code}, signal=${signal})\n${stderr}`,
      ));
    });
    child.once("error", (error) => {
      clearTimeout(timer);
      reject(error);
    });
  });
}

async function stop(child) {
  if (child.exitCode !== null || child.signalCode !== null) return;
  const exited = new Promise((resolve) => child.once("exit", resolve));
  child.kill("SIGTERM");
  let timer;
  const timeout = new Promise((resolve) => {
    timer = setTimeout(resolve, 3_000, "timeout");
  });
  try {
    if (await Promise.race([exited, timeout]) === "timeout") {
      child.kill("SIGKILL");
      await exited;
    }
  } finally {
    clearTimeout(timer);
  }
}

const server = spawn(process.execPath, [jiti, serverSource], {
  cwd: repoRoot,
  stdio: ["ignore", "pipe", "pipe"],
});

try {
  const url = await waitForServerUrl(server);
  const client = spawnSync(process.execPath, [jiti, clientSource, url], {
    cwd: repoRoot,
    encoding: "utf8",
    stdio: "pipe",
    timeout: 15_000,
  });
  if (client.status !== 0) {
    throw new Error(
      `Calculator client failed with ${client.status}\n${client.stdout}\n${client.stderr}`,
    );
  }
  const output = JSON.parse(client.stdout);
  assert.ok(output.tools.some((tool) => tool.name === "calculator_sum"));
  assert.deepEqual(output.result.structuredContent, { result: 5 });
  process.stdout.write(JSON.stringify({ ok: true, tool: "calculator_sum", result: 5 }) + "\n");
} finally {
  await stop(server);
}

import { build } from "esbuild";
import { Miniflare } from "miniflare";
const result = await build({
  stdin: {
    contents: `
    import { RateLimiter } from './plugfn/core/src/middleware/rate-limiter.ts';
    import { ExecutionCoordinator } from './plugfn/core/src/core/execution-coordinator.ts';
    import { cloudflareDurableObjectAtomicKVStore, SuperfunctionsStoresDurableObject } from './packages/db/src/adapters/cloudflare-do/index.ts';
    export { SuperfunctionsStoresDurableObject };
    export default { async fetch(request, env) {
      const store = cloudflareDurableObjectAtomicKVStore(env.STORES);
      if (new URL(request.url).pathname === '/quota') {
        const limiter = new RateLimiter({ atomicStore: store });
        const started = Date.now();
        try { await limiter.acquire('worker', { requests: 1, window: 300 }); return Response.json({ elapsed: Date.now() - started }); }
        finally { limiter.destroy(); }
      }
      const coordinator = new ExecutionCoordinator(store);
      try {
        const result = await coordinator.run('same-delivery', async () => {
          await new Promise(resolve => setTimeout(resolve, 200));
          return 'completed';
        });
        return Response.json({ result });
      } catch (error) { return Response.json({ error: error.message }, { status: 409 }); }
    }};
  `,
    resolveDir: process.cwd(),
    sourcefile: "sfns4-worker.ts",
    loader: "ts",
  },
  bundle: true,
  write: false,
  format: "esm",
  platform: "neutral",
  conditions: ["workerd", "worker", "import"],
  external: ["node:*"],
});
const modules = [
  {
    type: "ESModule",
    path: "sfns4-worker.mjs",
    contents: result.outputFiles[0].text,
  },
];
const compatibility = {
  compatibilityDate: "2026-09-13",
  compatibilityFlags: ["nodejs_compat"],
};
const mf = new Miniflare({
  workers: [
    {
      name: "a",
      ...compatibility,
      modules,
      durableObjects: {
        STORES: {
          className: "SuperfunctionsStoresDurableObject",
          scriptName: "store",
        },
      },
    },
    {
      name: "b",
      ...compatibility,
      modules,
      durableObjects: {
        STORES: {
          className: "SuperfunctionsStoresDurableObject",
          scriptName: "store",
        },
      },
    },
    {
      name: "store",
      ...compatibility,
      modules,
      durableObjects: { STORES: "SuperfunctionsStoresDurableObject" },
    },
  ],
});
try {
  const a = await mf.getWorker("a");
  const b = await mf.getWorker("b");
  const attempts = await Promise.all([
    a.fetch("https://example.test/work"),
    b.fetch("https://example.test/work"),
  ]);
  const statuses = attempts.map((response) => response.status).sort();
  if (JSON.stringify(statuses) !== "[200,409]")
    throw new Error(`Coordinator admitted duplicate isolates: ${statuses}`);
  for (const response of attempts) await response.text();
  const quota = await Promise.all([
    a.fetch("https://example.test/quota"),
    b.fetch("https://example.test/quota"),
  ]);
  const delays = await Promise.all(quota.map((response) => response.json()));
  if (!delays.some((result) => result.elapsed >= 200))
    throw new Error(`Quota was not shared: ${JSON.stringify(delays)}`);
  console.log(
    "workerd: two isolates share Durable Object quotas and admit only one concurrent workflow writer",
  );
} finally {
  await mf.dispose();
