import { Miniflare } from "miniflare";

const worker = `
import { z } from "zod";
import { McpFnRegistry, createMcpFnServer, structuredResult } from "@mcpfn/core";

const RootSchema = z.object({ n: z.number() });

export default {
  async fetch() {
    const server = createMcpFnServer({
      info: { name: "repro", version: "1.0.0" },
      registry: new McpFnRegistry().register({
        name: "sum",
        description: "Add two numbers.",
        inputSchema: { type: "object" },
        handler: async ({ a, b }) => structuredResult({ result: a + b }),
      }),
    });
    return Response.json({ ok: true, ready: Boolean(server), root: RootSchema.safeParse({ n: 1 }).success });
  },
};
`;

const result = await build({
  stdin: { contents: worker, resolveDir: process.cwd(), sourcefile: "worker.ts", loader: "ts" },
  bundle: true,
  write: false,
  format: "esm",
  platform: "neutral",
  mainFields: ["module", "main"],
  conditions: ["workerd", "worker", "browser", "import"],
  external: ["node:*"],
});

const mf = new Miniflare({
  compatibilityDate: "2026-09-13",
  compatibilityFlags: ["nodejs_compat"],
  modules: [{ type: "ESModule", path: "worker.mjs", contents: result.outputFiles[0].text }],
});

try {
  const response = await mf.dispatchFetch("https://example.test/");
  const body = await response.text();
  console.log(JSON.stringify({ ok: true, status: response.status, body }));
} catch (error) {
  console.error(JSON.stringify({ ok: false, error: error instanceof Error ? error.message : String(error) }));
  process.exitCode = 1;
} finally {
  await mf.dispose();
}

