import { z } from "zod";
import { McpFnRegistry, createMcpFnServer, structuredResult } from "@mcpfn/core";
import * as sdkTypes from "@modelcontextprotocol/sdk/types.js";

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const step = url.searchParams.get("step") || "all";
    const out = {};
    try {
      // 1) zod top-level init (root v4) + SDK zod/v4 schemas both loaded at import time.
      out.zodRoot = z.object({ n: z.number() }).safeParse({ n: 1 }).success;
      out.sdkSchema = Boolean(sdkTypes.InitializeRequestSchema);
      if (step === "zod") return Response.json({ ok: true, ...out });

      // 2) server with NO tools (no ajv compile path)
      const empty = createMcpFnServer({
        info: { name: "empty", version: "1.0.0" },
        registry: new McpFnRegistry(),
      });
      out.emptyServer = Boolean(empty);
      if (step === "empty") return Response.json({ ok: true, ...out });

      // 3) server WITH a tool (ajv compile path)
      const withTool = createMcpFnServer({
        info: { name: "tool", version: "1.0.0" },
        registry: new McpFnRegistry().register({
          name: "ping",
          description: "ok",
          inputSchema: { type: "object", additionalProperties: false },
          handler: async () => structuredResult({ ok: true }),
        }),
      });
      out.toolServer = Boolean(withTool);
      return Response.json({ ok: true, ...out });
    } catch (e) {
      return Response.json({ ok: false, out, error: e instanceof Error ? (e.stack || e.message) : String(e) }, { status: 500 });
    }
  },
};
EOF
